INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'senior', 'adj.', '/ˈsiːniə/', '(级别或年级)高的;年长的', 'My first day at senior high school was both exciting and scary.', '我高中的第一天既兴奋又害怕。', 'A New Start', 1, 0, 'senior', 'wordlist', 'required1', 'U1', 'senior high', NULL, 'fltrp');
