INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'impression', 'n.', '/ɪmˈpreʃ(ə)n/', '印象;感想', 'I wanted to make a good first impression on my new classmates.', '我想给新同学留下好的第一印象。', 'A New Start', 3, 0, 'senior', 'wordlist', 'required1', 'U1', 'a good first impression', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'campus', 'n.', '/ˈkæmpəs/', '校园', 'The campus was still quiet when I arrived early in the morning.', '我清晨早早到时,校园还很安静。', 'A New Start', 4, 0, 'senior', 'wordlist', 'required1', 'U1', 'explore the campus', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tradition', 'n.', '/trəˈdɪʃ(ə)n/', '传统;惯例', 'Welcoming new students with a concert is an old tradition at our school.', '用音乐会迎接新生是我们学校的老传统。', 'A New Start', 5, 0, 'senior', 'wordlist', 'required1', 'U1', 'a school tradition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'facility', 'n.', '/fəˈsɪlɪti/', '设施;设备', 'Our new school has modern sports facilities and a large library.', '我们的新学校有现代化的体育设施和一座大图书馆。', 'A New Start', 6, 0, 'senior', 'wordlist', 'required1', 'U1', 'sports facilities', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'impressive', 'adj.', '/ɪmˈpresɪv/', '令人钦佩的;给人深刻印象的', 'Lisa gave an impressive talk about her high school years.', '莉萨做了一场令人印象深刻的高中生活演讲。', 'A New Start', 7, 0, 'senior', 'wordlist', 'required1', 'U1', 'an impressive speech', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'moment', 'n.', '/ˈməʊmənt/', '时刻;片刻', 'I will never forget the moment I introduced myself to the class.', '我永远不会忘记向全班做自我介绍的那一刻。', 'A New Start', 8, 0, 'senior', 'wordlist', 'required1', 'U1', 'an embarrassing moment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'author', 'n.', '/ˈɔːθə/', '作者;作家', 'The author of the diary describes his first day at senior high.', '这篇日记的作者描述了他高中的第一天。', 'A New Start', 9, 0, 'senior', 'wordlist', 'required1', 'U1', 'the author of the diary', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'eagerness', 'n.', '/ˈiːɡənəs/', '热切;渴望', 'In my eagerness to explore the school, I rushed out of the door early.', '由于急切想探索学校,我一早就冲出了家门。', 'A New Start', 10, 0, 'senior', 'wordlist', 'required1', 'U1', 'in one''s eagerness', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'explore', 'v.', '/ɪkˈsplɔː/', '探索;考察', 'I decided to explore the campus before the first class began.', '第一节课开始前,我决定去探索一下校园。', 'A New Start', 11, 0, 'senior', 'wordlist', 'required1', 'U1', 'explore the school', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'engine', 'n.', '/ˈendʒɪn/', '发动机;引擎', 'I tried to turn on my brain, but the engine just would not start.', '我试图启动大脑,可这台引擎就是发动不起来。', 'A New Start', 12, 0, 'senior', 'wordlist', 'required1', 'U1', 'start the engine', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'insect', 'n.', '/ˈɪnsekt/', '昆虫', 'I thought of telling the class about my insect collection.', '我想过向全班介绍我的昆虫收藏。', 'A New Start', 13, 0, 'senior', 'wordlist', 'required1', 'U1', 'an insect collection', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'collection', 'n.', '/kəˈlekʃ(ə)n/', '收藏品;收集', 'He proudly showed us his collection of old coins.', '他自豪地向我们展示他的旧硬币收藏。', 'A New Start', 14, 0, 'senior', 'wordlist', 'required1', 'U1', 'a stamp collection', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'organise', 'v.', '/ˈɔːɡənaɪz/', '组织;安排;整理', 'I was still organising my words in my head when my turn came.', '轮到我时,我还在脑子里组织语言。', 'A New Start', 15, 0, 'senior', 'wordlist', 'required1', 'U1', 'organise one''s words', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'breathe', 'v.', '/briːð/', '呼吸', 'I breathed deeply and tried to stay calm before speaking.', '我深深地呼吸,努力在发言前保持镇定。', 'A New Start', 16, 0, 'senior', 'wordlist', 'required1', 'U1', 'breathe deeply', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'panic', 'n.', '/ˈpænɪk/', '惊恐;惊慌', 'When everyone laughed, I looked at them in panic.', '大家都笑起来时,我惊慌地看着他们。', 'A New Start', 17, 0, 'senior', 'wordlist', 'required1', 'U1', 'in panic', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'challenge', 'n.', '/ˈtʃæləndʒ/', '挑战;难题', 'Challenges like this might sometimes put you under pressure.', '这样的挑战有时会给你带来压力。', 'A New Start', 18, 0, 'senior', 'wordlist', 'required1', 'U1', 'face a challenge', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pressure', 'n.', '/ˈpreʃə/', '压力', 'New students often feel under pressure during the first week.', '新生在第一周常常感到压力很大。', 'A New Start', 19, 0, 'senior', 'wordlist', 'required1', 'U1', 'under pressure', NULL, 'fltrp');
