INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'description', 'n.', '/dɪˈskrɪpʃ(ə)n/', '描述;描写', 'Choose the best description of how he felt on his first day.', '选出对他第一天感受最恰当的描述。', 'A New Start', 21, 0, 'senior', 'wordlist', 'required1', 'U1', 'a clear description', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'confident', 'adj.', '/ˈkɒnfɪd(ə)nt/', '有信心的;自信的', 'After the class, he felt more confident about his future.', '课后,他对自己的未来更有信心了。', 'A New Start', 22, 0, 'senior', 'wordlist', 'required1', 'U1', 'feel confident', NULL, 'fltrp');
