INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'badminton', 'n.', '/ˈbædmɪntən/', '羽毛球', 'I joined the badminton club to stay fit and meet new people.', '我加入了羽毛球社,既能健身又能结识新朋友。', 'A New Start', 24, 0, 'senior', 'wordlist', 'required1', 'U1', 'play badminton', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'drama', 'n.', '/ˈdrɑːmə/', '戏剧;话剧', 'The drama club helps shy students find their inner star.', '戏剧社帮助腼腆的学生找到内心的明星。', 'A New Start', 25, 0, 'senior', 'wordlist', 'required1', 'U1', 'the drama club', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'band', 'n.', '/bænd/', '乐队;乐团', 'If you love music, you can play the piano or sing in a band.', '如果你爱音乐,可以弹钢琴或在乐队里唱歌。', 'A New Start', 26, 0, 'senior', 'wordlist', 'required1', 'U1', 'sing in a band', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'debate', 'n.', '/dɪˈbeɪt/', '辩论;讨论', 'In the debate club we argue about the week''s hottest topics.', '在辩论社,我们就本周最热门的话题展开辩论。', 'A New Start', 27, 0, 'senior', 'wordlist', 'required1', 'U1', 'a debate club', NULL, 'fltrp');
