INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stage', 'n.', '/steɪdʒ/', '舞台', 'One of my goals is to stand on stage at least once this year.', '我的目标之一是今年至少登台一次。', 'A New Start', 29, 0, 'senior', 'wordlist', 'required1', 'U1', 'stand on stage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'argue', 'v.', '/ˈɑːɡjuː/', '争论;争辩', 'Members of the debate club argue about important social issues.', '辩论社的成员就重要的社会议题进行争辩。', 'A New Start', 30, 0, 'senior', 'wordlist', 'required1', 'U1', 'argue about', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'topic', 'n.', '/ˈtɒpɪk/', '话题;论题', 'Each week we choose a new topic for our group discussion.', '每周我们都为小组讨论选一个新话题。', 'A New Start', 31, 0, 'senior', 'wordlist', 'required1', 'U1', 'a hot topic', NULL, 'fltrp');
