INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'volunteer', 'n.', '/ˌvɒlənˈtɪə/', '志愿者', 'Many senior high students do volunteer work in their free time.', '许多高中生在空闲时间做志愿工作。', 'A New Start', 36, 0, 'senior', 'wordlist', 'required1', 'U1', 'volunteer work', NULL, 'fltrp');
