INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'apply', 'v.', '/əˈplaɪ/', '申请;应用', 'Such activities also count when students apply to college.', '学生申请大学时,这些活动也会被考虑。', 'A New Start', 38, 0, 'senior', 'wordlist', 'required1', 'U1', 'apply to college', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'schedule', 'n.', '/ˈʃedjuːl/', '计划表;日程表', 'Students must learn to organise their busy schedules.', '学生必须学会安排自己繁忙的日程。', 'A New Start', 39, 0, 'senior', 'wordlist', 'required1', 'U1', 'a busy schedule', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'award', 'n.', '/əˈwɔːd/', '奖;奖赏', 'One of her goals was to win an award before leaving school.', '她的目标之一是在毕业前赢得一个奖项。', 'A New Start', 40, 0, 'senior', 'wordlist', 'required1', 'U1', 'win an award', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'opportunity', 'n.', '/ˌɒpəˈtjuːnɪti/', '机会;时机', 'Orientation Day is a great opportunity to get to know the school.', '迎新日是了解学校的好机会。', 'A New Start', 41, 0, 'senior', 'wordlist', 'required1', 'U1', 'a great opportunity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'former', 'adj.', '/ˈfɔːmə/', '从前的;以前的', 'Lisa is a former student who graduated from our school last June.', '莉萨是去年六月从我们学校毕业的一名往届学生。', 'A New Start', 42, 0, 'senior', 'wordlist', 'required1', 'U1', 'a former student', NULL, 'fltrp');
