INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'frightened', 'adj.', '/ˈfraɪtnd/', '受惊的;害怕的', 'Lisa was frightened at the sight of her first test paper.', '莉萨一看到第一张试卷就害怕了。', 'A New Start', 44, 0, 'senior', 'wordlist', 'required1', 'U1', 'be frightened', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'select', 'v.', '/səˈlekt/', '挑选;选择', 'She was not selected for the end-of-year competition.', '她没有入选年终比赛。', 'A New Start', 45, 0, 'senior', 'wordlist', 'required1', 'U1', 'be selected', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'neat', 'adj.', '/niːt/', '好的;整洁的;令人愉快的', '"Neat!" said the interviewer when he heard Lisa''s advice.', '听到莉萨的建议,采访者说:"太棒了!"', 'A New Start', 46, 0, 'senior', 'wordlist', 'required1', 'U1', 'a neat idea', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'specific', 'adj.', '/spəˈsɪfɪk/', '具体的;特定的', 'When you scan a text, you look for a specific piece of information.', '略读文章时,你要寻找某条具体信息。', 'A New Start', 47, 0, 'senior', 'wordlist', 'required1', 'U1', 'specific information', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'journal', 'n.', '/ˈdʒɜːnl/', '日记;日志', 'I wrote a journal entry about my first week at senior high.', '我写了一篇关于高中第一周的日记。', 'A New Start', 48, 0, 'senior', 'wordlist', 'required1', 'U1', 'a journal entry', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'junior', 'adj.', '/ˈdʒuːniə/', '低年级的;年少的', 'At junior high, I took lots of notes during every class.', '在初中时,我每节课都记很多笔记。', 'A New Start', 49, 0, 'senior', 'wordlist', 'required1', 'U1', 'junior high', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'struggle', 'v.', '/ˈstrʌɡ(ə)l/', '奋斗;艰难地做;挣扎', 'The teacher saw that I was struggling with note-taking.', '老师看出我在记笔记上很吃力。', 'A New Start', 50, 0, 'senior', 'wordlist', 'required1', 'U1', 'struggle with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'improve', 'v.', '/ɪmˈpruːv/', '改善;改进;提高', 'As a class member, I thought about how to improve our school.', '作为班级一员,我思考着如何改善我们的学校。', 'A New Start', 51, 0, 'senior', 'wordlist', 'required1', 'U1', 'improve my school', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u1.01', '①主谓宾宾(SVOO):能带双宾语的动词(give/tell/show… sb sth)', 'A2', 10, '外研社版必修第一册 U1 — 有些动词后面可以接两个宾语——先接''人''(间接宾语)、再接''物''(直接宾语),如 give me a book。不及物动词(arrive/happen/stay…)后面不能带宾语,更不能带两个宾语。', 1, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u1.02', '②主谓宾补(SVOC):make/keep/find… + 宾语 + 形容词作宾语补足语', 'A2', 10, '外研社版必修第一册 U1 — make/keep/find/leave/get 等后面常接''宾语 + 形容词'',形容词说明宾语的状态(make me happy)。这里只能用形容词,不能用副词、名词或不定式。', 2, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u1.03', '③主系表(SVP):系动词 be/feel/look/become… + 形容词作表语', 'A2', 10, '外研社版必修第一册 U1 — 系动词(be/feel/look/become/seem/sound/get/stay/grow 等)后面接形容词作表语,说明主语的状态(I feel nervous)。系动词后用形容词,不用副词、名词或不定式。', 3, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'My new teacher ____ me a useful book about good study habits.', 'gave', 'arrived', 'happened', 'stayed', 'A', 'give 可接双宾语(give sb sth),这里''me''与''a useful book''是两个宾语;arrive/happen/stay 是不及物动词,不能带宾语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'On my first day, a kind senior ____ me some helpful advice.', 'smiled', 'offered', 'waited', 'slept', 'B', 'offer sb sth 接双宾语;smile/wait/sleep 不及物,不能带''me … advice''两个宾语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'The head teacher ____ the new students an interesting story about the school.', 'came', 'appeared', 'told', 'laughed', 'C', 'tell sb sth 接双宾语;come/appear/laugh 不及物动词,不能带双宾语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'A friendly classmate ____ me the way to the science lab.', 'sat', 'ran', 'fell', 'showed', 'D', 'show sb sth 接双宾语;sit/run/fall 不及物,不能接''me … the way''。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'The school ____ every new student a welcome letter before term began.', 'sent', 'arrived', 'happened', 'rose', 'A', 'send sb sth 接双宾语;arrive/happen/rise 不及物动词,不能带宾语。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'Lisa ____ us a box of photos from her own high school days.', 'smiled', 'brought', 'waited', 'listened', 'B', 'bring sb sth 接双宾语;smile/wait/listen 不及物,不能带''us … a box''。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'Mr Meng ____ us a simple way to stay calm under pressure.', 'arrived', 'stayed', 'taught', 'slept', 'C', 'teach sb sth 接双宾语;arrive/stay/sleep 不及物,不能带双宾语。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'The teacher ____ each of us a copy of the new timetable.', 'came', 'appeared', 'laughed', 'handed', 'D', 'hand sb sth 接双宾语;come/appear/laugh 不及物动词,后面不能跟宾语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'The girl next to me ____ me a pen when I forgot mine.', 'passed', 'sat', 'ran', 'fell', 'A', 'pass sb sth 接双宾语;sit/run/fall 不及物,不能带''me a pen''。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'A senior student kindly ____ me her notes before the first test.', 'arrived', 'lent', 'happened', 'rose', 'B', 'lend sb sth 接双宾语;arrive/happen/rise 不及物,不能带宾语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'At the end of the year, the school ____ her a prize for hard work.', 'smiled', 'waited', 'awarded', 'slept', 'C', 'award sb sth 接双宾语;smile/wait/sleep 不及物,不能带''her a prize''。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'The interviewer ____ Lisa several questions about her first week.', 'came', 'appeared', 'laughed', 'asked', 'D', 'ask sb sth 接双宾语;come/appear/laugh 不及物动词,不能带双宾语。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'His encouraging words ____ me real confidence on a difficult day.', 'gave', 'arrived', 'stayed', 'fell', 'A', 'give sb sth 接双宾语;arrive/stay/fall 不及物,不能带''me … confidence''。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'The club leader ____ us a free lesson to help us decide.', 'sat', 'offered', 'ran', 'waited', 'B', 'offer sb sth 接双宾语;sit/run/wait 不及物,不能带宾语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'Sarah ____ me a few easy skateboarding tricks after class.', 'smiled', 'happened', 'showed', 'rose', 'C', 'show sb sth 接双宾语;smile/happen/rise 不及物,不能带双宾语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'Our teacher ____ us the reason why a good start really matters.', 'arrived', 'slept', 'laughed', 'told', 'D', 'tell sb sth 接双宾语;arrive/sleep/laugh 不及物动词,不能带宾语。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'The committee ____ every member a message about the first meeting.', 'sent', 'came', 'appeared', 'sat', 'A', 'send sb sth 接双宾语;come/appear/sit 不及物,不能带''every member a message''。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'Mum ____ me a warm drink while I planned my weekly schedule.', 'ran', 'brought', 'fell', 'waited', 'B', 'bring sb sth 接双宾语;run/fall/wait 不及物,不能带双宾语。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'The band teacher ____ us a new song for the welcome concert.', 'smiled', 'happened', 'taught', 'rose', 'C', 'teach sb sth 接双宾语;smile/happen/rise 不及物动词,不能带宾语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.01'), 'Before the speech, Lisa ____ the host a short list of her main points.', 'arrived', 'slept', 'laughed', 'handed', 'D', 'hand sb sth 接双宾语;arrive/sleep/laugh 不及物,不能带''the host a short list''。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'The teacher''s warm smile made the whole class ____.', 'happy', 'happily', 'happiness', 'to happy', 'A', 'make + 宾语 + 形容词作宾补,形容词说明 class 的状态;副词 happily、名词 happiness、不定式都不能作宾补。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'Taking a deep breath made me ____ before my speech.', 'calmly', 'calm', 'calmness', 'to calm', 'B', 'make me + 形容词,calm 作宾补说明''我''的状态;副词/名词/不定式都不能放在这里。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'On the first morning, I found myself rather ____.', 'nervously', 'nervousness', 'nervous', 'to nervous', 'C', 'find + 宾语 + 形容词,nervous 说明 myself 的状态;副词、名词、不定式都不能作宾补。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'Mr Meng''s advice made every new student more ____.', 'confidently', 'confidence', 'to confident', 'confident', 'D', 'make … + 形容词作宾补,more confident 说明 student 的状态;副词/名词/不定式不能作宾补。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'The mystery on the noticeboard kept us ____ all morning.', 'curious', 'curiously', 'curiosity', 'to curious', 'A', 'keep + 宾语 + 形容词,curious 说明 us 的状态;副词、名词、不定式都不行。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'The empty campus kept everything ____ in the early morning.', 'quietly', 'quiet', 'quietness', 'to quiet', 'B', 'keep everything + 形容词作宾补;副词 quietly、名词 quietness、不定式都不能作宾补。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'Standing on the stage made my parents very ____.', 'proudly', 'pride', 'proud', 'to proud', 'C', 'make … + 形容词,proud 说明 parents 的状态;副词/名词 pride/不定式都不能作宾补。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'After a week, I found the new classroom quite ____.', 'comfortably', 'comfort', 'to comfortable', 'comfortable', 'D', 'find + 宾语 + 形容词,comfortable 说明 classroom 的状态;副词、名词、不定式都不行。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'Missing the club meeting left me a little ____.', 'sad', 'sadly', 'sadness', 'to sad', 'A', 'leave + 宾语 + 形容词作宾补,sad 说明 me 的状态;副词/名词/不定式不能作宾补。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'Good time management keeps a busy student ____ from too much stress.', 'safely', 'safe', 'safety', 'to safe', 'B', 'keep + 宾语 + 形容词,safe 说明 student 的状态;副词 safely、名词 safety、不定式都不能作宾补。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'The lively welcome concert made everyone ____.', 'cheerfully', 'cheerfulness', 'cheerful', 'to cheerful', 'C', 'make … + 形容词作宾补;副词、名词、不定式都不能放在 everyone 之后。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'I found the debate club rather ____ about winning.', 'seriously', 'seriousness', 'to serious', 'serious', 'D', 'find + 宾语 + 形容词,serious 说明 club 的态度;副词/名词/不定式不能作宾补。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'Joining the sports club keeps my body ____ and healthy.', 'active', 'actively', 'action', 'to active', 'A', 'keep + 宾语 + 形容词,active 说明 body 的状态;副词 actively、名词 action、不定式都不行。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'Mr Meng''s simple example made the whole lesson very ____.', 'clearly', 'clear', 'clarity', 'to clear', 'B', 'make … + 形容词作宾补,clear 说明 lesson 的状态;副词、名词、不定式都不能作宾补。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.02'), 'We got the classroom ____ for the welcome party.', 'readily', 'readiness', 'ready', 'to ready', 'C', 'get + 宾语 + 形容词,ready 说明 classroom 的状态;副词 readily、名词 readiness、不定式都不能作宾补。', 2, 15, 'mcq');
