INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'Mr Meng''s voice sounded ____ but kind.', 'seriously', 'seriousness', 'to serious', 'serious', 'D', 'sound 是系动词,后接形容词作表语;副词/名词/不定式都不行。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'After making a few friends, I became more ____.', 'cheerful', 'cheerfully', 'cheerfulness', 'to cheerful', 'A', 'become 作系动词,后接形容词 cheerful 作表语;副词、名词、不定式都不能作表语。', 2, 9, 'mcq');
