INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'The science lab looked clean and ____.', 'brightly', 'brightness', 'bright', 'to bright', 'C', 'look 作系动词,后接形容词作表语;副词 brightly、名词 brightness、不定式都不能作表语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'After Mr Meng''s example, the rule seemed quite ____.', 'clearly', 'clarity', 'to clear', 'clear', 'D', 'seem 是系动词,后接形容词作表语;副词/名词 clarity/不定式都不能作表语。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'With my new friends around, I felt ____ and welcome.', 'safe', 'safely', 'safety', 'to safe', 'A', 'feel 作系动词,后接形容词 safe 作表语;副词 safely、名词 safety、不定式都不行。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'When I missed the team, I felt a little ____.', 'sadly', 'sad', 'sadness', 'to sad', 'B', 'feel 是系动词,后接形容词作表语;副词、名词 sadness、不定式都不能作表语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'Everyone''s welcome on the first day was friendly and ____.', 'warmly', 'warmth', 'warm', 'to warm', 'C', 'be 是系动词,后接形容词作表语;副词 warmly、名词 warmth、不定式都不行。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'To most of us, the orientation talk seemed very ____.', 'helpfully', 'helpfulness', 'to helpful', 'helpful', 'D', 'seem 作系动词,后接形容词 helpful 作表语;副词、名词、不定式都不能作表语。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'When the teacher entered, we all became ____.', 'silent', 'silently', 'silence', 'to silent', 'A', 'become 是系动词,后接形容词作表语;副词、名词 silence、不定式都不行。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'After a good night''s sleep, I felt ____ for the first class.', 'freshly', 'fresh', 'freshness', 'to fresh', 'B', 'feel 作系动词,后接形容词作表语;副词 freshly、名词 freshness、不定式都不能作表语。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'Even when nervous, Lisa stayed ____ and friendly.', 'politely', 'politeness', 'polite', 'to polite', 'C', 'stay 是系动词,后接形容词作表语;副词 politely、名词 politeness、不定式都不行。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U1' AND code='f1u1.03'), 'Day by day, I grew more ____ about senior high life.', 'eagerly', 'eagerness', 'to eager', 'eager', 'D', 'grow 作系动词,后接形容词 eager 作表语;副词 eagerly、名词 eagerness、不定式都不能作表语。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'My First Day at Senior High', 'After picturing it many times in my mind, the big day finally arrived: my first day at senior high. In my eagerness to know my new school, I woke up early and rushed out of the door. The campus was still quiet when I got there, so I decided to explore a little. While I was looking at the photos on the noticeboard, a white-haired man behind me asked, "New here?" "Yes," I said. "I am wondering what life will be like." He smiled and told me I would soon find out. Later, when my English teacher walked into the classroom, I was surprised to see the same man. During the lesson he asked us to introduce ourselves one by one. With butterflies in my stomach, I breathed deeply and said my name. To my shock, it was the same as the teacher''s, and everyone laughed. Although I felt embarrassed, his kind words made me a lot more relaxed.', '记叙·高中第一天', 159, '[{"q":"Why did the writer wake up early on the first day?","answer":"A","options":["He was eager to get to know his new school.","He had to take an early exam.","His teacher had asked him to come early.","He wanted to avoid meeting anyone."],"explanation":"原文 ''In my eagerness to know my new school, I woke up early'' 的转述。"},{"q":"Who turned out to be the white-haired man?","answer":"B","options":["A new classmate.","The writer''s English teacher.","A school cleaner.","The writer''s father."],"explanation":"原文 ''when my English teacher walked into the classroom, I was surprised to see the same man''。"},{"q":"How did the writer feel after the teacher''s kind words?","answer":"A","options":["Much more relaxed.","Even more frightened than before.","Angry at his classmates.","Bored with the lesson."],"explanation":"末句 ''his kind words made me a lot more relaxed'' 的转述。"}]'::jsonb, '[{"word":"campus","cn":"校园"},{"word":"eagerness","cn":"渴望"},{"word":"breathe","cn":"呼吸"}]'::jsonb, 2, 'required1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Advice from a Former Student', 'On the show School Talk, a former student named Lisa shared her suggestions for senior high. Lisa graduated last June and is about to start college in New York. She said Orientation Day had helped her most, because it was a great chance to get to know the school and meet other students. Her advice was simple: keep an open mind and take part in as much as possible. When the interviewer asked how she dealt with new challenges, Lisa remembered a chemistry test at the end of her first week. She was frightened at the sight of the paper, but she decided to go all out and see what happened. "If you fail," she said with a smile, "next time you can fail better." She also talked about a disappointment: she was not selected for an important competition. Even so, she kept working hard to support her teammates, because she loved the sport itself, not just winning.', '访谈·前辈的建议', 158, '[{"q":"What did Lisa find most helpful when she started senior high?","answer":"B","options":["The chemistry test.","Orientation Day.","Joining the volleyball team.","Moving to New York."],"explanation":"原文 ''Orientation Day had helped her most''。"},{"q":"What did Lisa decide to do about the difficult chemistry test?","answer":"C","options":["She refused to take it.","She copied another student.","She gave it her best effort.","She asked to leave early."],"explanation":"原文 ''she decided to go all out'' 的转述(全力以赴)。"},{"q":"Why did Lisa keep working hard after not being selected?","answer":"D","options":["She wanted to win a prize.","Her coach forced her to.","She hoped to leave the team.","She loved the sport, not just winning."],"explanation":"末句 ''because she loved the sport itself, not just winning'' 的转述。"}]'::jsonb, '[{"word":"former","cn":"从前的"},{"word":"graduate","cn":"毕业"},{"word":"select","cn":"挑选"}]'::jsonb, 2, 'required1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'School Clubs for Everyone', 'One of the best ways to enjoy senior high is to join a school club. Our school offers many different clubs, so there is something for everyone. If you love sport, the badminton club meets in the gym every Tuesday to help you stay fit and make new friends. Music lovers can play the piano or sing in a band at the Music Room. Those who enjoy thinking about big questions may like the science club, where members investigate why dolphins are so clever or what killed the dinosaurs. The debate club brings together the sharpest minds in the school to argue about the week''s hottest topics. If acting is your dream, the drama club can help you find your inner star on the stage. Joining a club does more than fill your free time. It helps you gain new skills, care about others and feel part of the school. So look at the posters, choose a club, and give it a try.', '说明·校园社团', 163, '[{"q":"Where does the badminton club meet?","answer":"A","options":["In the gym.","In the Music Room.","On the stage.","At the library."],"explanation":"原文 ''the badminton club meets in the gym every Tuesday''。"},{"q":"What do members of the science club do?","answer":"B","options":["Sing songs together.","Look into questions about nature.","Practise acting on stage.","Play badminton matches."],"explanation":"原文 ''investigate why dolphins are so clever or what killed the dinosaurs'' 的转述。"},{"q":"According to the text, what is one benefit of joining a club?","answer":"C","options":["It costs a lot of money.","It keeps students away from friends.","It helps students build new skills and a sense of belonging.","It replaces all schoolwork."],"explanation":"原文 ''It helps you gain new skills… and feel part of the school'' 的转述。"}]'::jsonb, '[{"word":"investigate","cn":"调查"},{"word":"debate","cn":"辩论"},{"word":"gain","cn":"获得"}]'::jsonb, 2, 'required1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'After-School Activities and Time', 'In the UK and the US, senior high students take part in many after-school activities, such as club activities and volunteer work. These activities are good for them in several ways. They not only help students gain useful skills, but also teach them to care about other people. After-school activities can play a part when students later apply to college, too. However, there is a problem. Such activities can take up a lot of time, so students have to learn to organise their busy schedules. If they are not careful, they may feel under pressure and fall behind in their studies. To help with this, some senior high schools now offer courses in time management. In these courses, students learn simple skills: list the things they plan to do, decide how long each one will take, and do the most important tasks first. With a clear plan, a busy week feels much easier to handle.', '说明·课后活动与时间管理', 155, '[{"q":"What is one benefit of after-school activities mentioned in the text?","answer":"D","options":["They give students more money.","They make schoolwork unnecessary.","They shorten the school day.","They teach students to care about others."],"explanation":"原文 ''teach them to care about other people'' 的转述。"},{"q":"Why do some schools offer courses in time management?","answer":"A","options":["Because such activities can use up much of students'' time.","Because students have nothing to do.","Because students dislike clubs.","Because teachers have free lessons."],"explanation":"原文 ''activities can take up a lot of time, so students have to learn to organise their busy schedules'' 的转述。"},{"q":"What is one skill taught in a time-management course?","answer":"B","options":["Doing the easiest tasks last only.","Handling the most urgent work before easier jobs.","Avoiding all clubs.","Spending all day on one activity."],"explanation":"原文 ''do the most important tasks first'' 的转述。"}]'::jsonb, '[{"word":"volunteer","cn":"志愿者"},{"word":"apply","cn":"申请"},{"word":"schedule","cn":"日程表"}]'::jsonb, 2, 'required1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'My First Week: A Journal', 'Finally, it is Friday, and I can hardly believe my first week is coming to an end. Things are going well, but there is always something new just around the corner. At junior high, I took lots of notes in every class, so in physics on Monday I did the same. The teacher spoke so fast that I could not write everything down. He noticed I was struggling and told me to stop and just listen. "Thinking is more important than copying down every word," he said. After class on Wednesday, I hurried to the skateboarding club. On my way out, I bumped into a girl and quickly said sorry. At the club, I tried skateboarding for the first time and fell off the board again and again. Suddenly the same girl bumped into me, and this time we both laughed. Her name is Sarah, and we soon became friends. Tomorrow we are going to watch a film together, and I am really looking forward to it.', '记叙·第一周日记', 167, '[{"q":"What problem did the writer have in the physics class?","answer":"C","options":["The room was too dark to see.","There were no seats left.","The teacher spoke too fast to copy everything.","She forgot her textbook."],"explanation":"原文 ''The teacher spoke so fast that I could not write everything down'' 的转述。"},{"q":"What did the physics teacher advise the writer to do?","answer":"D","options":["Copy every word carefully.","Leave the class early.","Change to another subject.","Stop writing and just listen."],"explanation":"原文 ''told me to stop and just listen'' 的转述。"},{"q":"How did the writer make friends with Sarah?","answer":"A","options":["They bumped into each other and laughed at the club.","They sat together in physics.","They were in the same band.","Their parents knew each other."],"explanation":"原文 ''the same girl bumped into me, and this time we both laughed… we soon became friends'' 的转述。"}]'::jsonb, '[{"word":"junior","cn":"低年级的"},{"word":"struggle","cn":"奋斗;吃力"},{"word":"memorise","cn":"记住"}]'::jsonb, 2, 'required1', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Well Begun, Half Done', 'People often say, "Well begun is half done." For students starting senior high, a good beginning really does matter. The first few weeks can be hard. You meet new teachers, learn a new timetable and try to make a good first impression. Challenges like these may put you under pressure, but how things turn out depends a lot on what you do. The first piece of advice is to keep calm and be prepared. If you plan your time and ask for help when you need it, problems feel much smaller. The second is to keep an open mind. Join clubs, talk to new classmates and try things you have never done before. You may fail at first, but every mistake is a chance to learn. Finally, remember to give your friends a hand. Helping others not only makes them feel welcome, but also makes you feel good. With a calm mind and an open heart, you can make the most of your time at senior high.', '议论·好的开始', 167, '[{"q":"What does the saying \"Well begun is half done\" suggest here?","answer":"B","options":["Beginnings do not matter at all.","A good start is very important.","Students should start work late.","Half the work is always wasted."],"explanation":"原文 ''a good beginning really does matter'' 的转述。"},{"q":"What is the writer''s first piece of advice?","answer":"C","options":["Avoid all clubs.","Copy other students'' work.","Stay calm and be prepared.","Never ask anyone for help."],"explanation":"原文 ''keep calm and be prepared'' 的转述。"},{"q":"According to the writer, what does helping friends do for you?","answer":"D","options":["It wastes your study time.","It makes others dislike you.","It has no effect at all.","It makes you feel good, too."],"explanation":"原文 ''Helping others… also makes you feel good'' 的转述。"}]'::jsonb, '[{"word":"impression","cn":"印象"},{"word":"pressure","cn":"压力"},{"word":"calm","cn":"镇静的"}]'::jsonb, 2, 'required1', 'U1', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'The Morning of My First Day', 'When my alarm rang on the first morning of senior high, I was already (1)____. I had (2)____ about this day for weeks. I jumped out of bed, put on my new clothes, and (3)____ my breakfast quickly. In my (4)____ to reach the school early, I almost forgot my schoolbag. The streets were quiet, and my heart beat fast as I (5)____ towards the gate. More than anything, I wanted to make a good first (6)____ on my teachers and classmates. When I reached the (7)____, it was still empty and peaceful. I decided to (8)____ the buildings before class began. Everything looked new and (9)____ to me. By the time the bell rang, I felt both nervous and (10)____ about the year ahead.', 125, 2, '[{"q":"1","answer":"A","options":["awake","asleep","late","lost"],"explanation":"already awake 早已醒着。"},{"q":"2","answer":"B","options":["cleaned","dreamed","sold","lost"],"explanation":"dreamed about this day 梦想着这一天。"},{"q":"3","answer":"C","options":["sold","threw","ate","lost"],"explanation":"ate my breakfast 吃了早饭。"},{"q":"4","answer":"D","options":["silence","darkness","weather","eagerness"],"explanation":"in my eagerness to 急切地想……。"},{"q":"5","answer":"A","options":["hurried","slept","sat","fell"],"explanation":"hurried towards the gate 急忙走向大门。"},{"q":"6","answer":"B","options":["mistake","impression","noise","price"],"explanation":"a good first impression 良好的第一印象。"},{"q":"7","answer":"C","options":["kitchen","station","campus","forest"],"explanation":"reached the campus 到了校园。"},{"q":"8","answer":"D","options":["sell","throw","forget","explore"],"explanation":"explore the buildings 探索教学楼。"},{"q":"9","answer":"A","options":["exciting","boring","empty","asleep"],"explanation":"new and exciting 新奇又令人兴奋。"},{"q":"10","answer":"B","options":["angry","excited","bored","asleep"],"explanation":"nervous and excited 既紧张又兴奋。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'Choosing a Club', 'During the first week, our teacher told us to (1)____ a school club. There were so many (2)____ to choose from that I did not know where to start. I love sport, so at first I thought about the (3)____ club, where students play in the gym. Then I saw a (4)____ for the science club on the wall. It asked interesting questions and invited us to (5)____ the secrets of nature. My best friend wanted to join the (6)____ club, because she loves to argue about hot (7)____. In the end, I chose the drama club, hoping to find my (8)____ star on the stage. At our first meeting, the leader (9)____ us some simple acting skills. I felt shy at first, but soon I (10)____ a lot of confidence.', 131, 2, '[{"q":"1","answer":"C","options":["sell","lose","join","forget"],"explanation":"join a club 加入社团。"},{"q":"2","answer":"D","options":["prices","noises","seasons","clubs"],"explanation":"many clubs to choose from 许多社团可选。"},{"q":"3","answer":"A","options":["badminton","kitchen","station","garden"],"explanation":"the badminton club 羽毛球社。"},{"q":"4","answer":"B","options":["price","poster","noise","meal"],"explanation":"a poster for the club 社团海报。"},{"q":"5","answer":"C","options":["sell","forget","investigate","lose"],"explanation":"investigate the secrets 探究奥秘。"},{"q":"6","answer":"D","options":["kitchen","garden","station","debate"],"explanation":"the debate club 辩论社。"},{"q":"7","answer":"A","options":["topics","prices","meals","clouds"],"explanation":"argue about hot topics 辩论热门话题。"},{"q":"8","answer":"B","options":["empty","inner","broken","late"],"explanation":"my inner star 内心的明星。"},{"q":"9","answer":"C","options":["sold","lost","taught","threw"],"explanation":"taught us some skills 教我们技能。"},{"q":"10","answer":"D","options":["lost","sold","dropped","gained"],"explanation":"gained confidence 获得自信。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'How I Made a New Friend', 'On Wednesday after class, I (1)____ to the skateboarding club. I was running out of the classroom when I (2)____ into a girl. I quickly said sorry, and she gave me a (3)____ smile. At the club, I tried skateboarding for the first time and (4)____ off the board again and again. It was hard, but I did not give (5)____. Suddenly, the same girl bumped into me, and this time we both (6)____. Her name was Sarah. We started to (7)____ together, and slowly my skills got (8)____. By the end of the lesson, we had become good (9)____. Tomorrow we are going to watch a film, and I am really looking (10)____ to it.', 116, 2, '[{"q":"1","answer":"A","options":["hurried","slept","sat","grew"],"explanation":"hurried to the club 急忙赶去社团。"},{"q":"2","answer":"B","options":["sold","bumped","lost","sang"],"explanation":"bumped into a girl 撞到一个女孩。"},{"q":"3","answer":"C","options":["broken","empty","friendly","late"],"explanation":"a friendly smile 友好的微笑。"},{"q":"4","answer":"D","options":["sold","sang","grew","fell"],"explanation":"fell off the board 从滑板上摔下来。"},{"q":"5","answer":"A","options":["up","at","of","from"],"explanation":"give up 放弃。"},{"q":"6","answer":"B","options":["slept","laughed","sold","grew"],"explanation":"we both laughed 我们都笑了。"},{"q":"7","answer":"C","options":["sell","lose","practise","forget"],"explanation":"practise together 一起练习。"},{"q":"8","answer":"D","options":["worse","empty","late","better"],"explanation":"got better 越来越好。"},{"q":"9","answer":"A","options":["friends","prices","clouds","machines"],"explanation":"good friends 好朋友。"},{"q":"10","answer":"B","options":["back","forward","down","away"],"explanation":"look forward to 期待。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'Managing My Time', 'At senior high, there is always a lot to do, so I had to learn to (1)____ my time. In my first week, I joined two clubs and still had a lot of (2)____ to finish every night. Soon I began to feel under (3)____. My teacher gave me a useful (4)____: make a clear plan. First, I write a (5)____ of all the things I need to do. Then I decide how long each task will (6)____. I always do the most (7)____ tasks first, and leave the easy ones for later. This simple habit has helped me a lot. Now my week feels much less (8)____, and I rarely (9)____ behind. With a good plan, I can enjoy my clubs and still (10)____ good marks.', 127, 2, '[{"q":"1","answer":"C","options":["sell","lose","organise","forget"],"explanation":"organise my time 安排时间。"},{"q":"2","answer":"D","options":["weather","music","sleep","homework"],"explanation":"a lot of homework 大量作业。"},{"q":"3","answer":"A","options":["pressure","water","music","light"],"explanation":"under pressure 有压力。"},{"q":"4","answer":"B","options":["price","tip","noise","song"],"explanation":"a useful tip 有用的建议。"},{"q":"5","answer":"C","options":["price","song","list","cloud"],"explanation":"write a list 列一张清单。"},{"q":"6","answer":"D","options":["sell","lose","sing","take"],"explanation":"how long each task will take 每项任务要花多久。"},{"q":"7","answer":"A","options":["important","empty","late","quiet"],"explanation":"the most important tasks 最重要的任务。"},{"q":"8","answer":"B","options":["empty","busy","late","quiet"],"explanation":"much less busy 不那么忙。"},{"q":"9","answer":"C","options":["sell","sing","fall","grow"],"explanation":"fall behind 落后。"},{"q":"10","answer":"D","options":["lose","sell","drop","get"],"explanation":"get good marks 取得好成绩。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'Introducing Myself in Class', 'During my first English lesson, the teacher asked us to introduce ourselves one by (1)____. With butterflies in my (2)____, I waited for my turn. I tried to (3)____ my words in my head, but my mind went blank. When the girl next to me gave me a (4)____, I knew it was my turn. I stood up, (5)____ deeply, and said my name. To my surprise, everyone began to (6)____. It turned out that I (7)____ exactly the same name as the teacher! Although I felt (8)____ at that moment, the teacher''s kind words made me feel more (9)____. From that lesson on, I was sure this class would be a (10)____ place.', 114, 2, '[{"q":"1","answer":"A","options":["one","two","day","week"],"explanation":"one by one 一个接一个。"},{"q":"2","answer":"B","options":["garden","stomach","station","kitchen"],"explanation":"butterflies in my stomach 心里发慌。"},{"q":"3","answer":"C","options":["sell","lose","organise","forget"],"explanation":"organise my words 组织语言。"},{"q":"4","answer":"D","options":["price","song","cloud","nudge"],"explanation":"gave me a nudge 轻推了我一下。"},{"q":"5","answer":"A","options":["breathed","sold","sang","grew"],"explanation":"breathed deeply 深深呼吸。"},{"q":"6","answer":"B","options":["sleep","laugh","sell","grow"],"explanation":"began to laugh 开始笑。"},{"q":"7","answer":"C","options":["sold","lost","had","sang"],"explanation":"I had the same name 我和老师同名。"},{"q":"8","answer":"D","options":["happy","asleep","hungry","embarrassed"],"explanation":"felt embarrassed 感到尴尬。"},{"q":"9","answer":"A","options":["relaxed","angry","asleep","hungry"],"explanation":"feel more relaxed 感到更放松。"},{"q":"10","answer":"B","options":["broken","friendly","empty","late"],"explanation":"a friendly place 友好的地方。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'Advice for New Students', 'If you are just starting senior high, here is some (1)____ that may help. First, keep an open (2)____ and try as many new things as you can. Join a club, talk to new (3)____, and take part in school events. You may (4)____ at first, but every mistake is a chance to learn. Second, do not be afraid to (5)____ for help. Your teachers and classmates are happy to give you a (6)____. Third, learn to (7)____ your time well, so that you do not feel too much pressure. Finally, remember to help (8)____ when they need it. Being kind not only makes them feel (9)____, but also makes you feel good. With a calm mind and an open heart, you can make the (10)____ of your time at high school.', 132, 2, '[{"q":"1","answer":"C","options":["weather","music","advice","water"],"explanation":"some advice 一些建议。"},{"q":"2","answer":"D","options":["price","song","cloud","mind"],"explanation":"keep an open mind 保持开放心态。"},{"q":"3","answer":"A","options":["classmates","prices","clouds","machines"],"explanation":"new classmates 新同学。"},{"q":"4","answer":"B","options":["sell","fail","sing","grow"],"explanation":"you may fail 你可能失败。"},{"q":"5","answer":"C","options":["sell","sleep","ask","grow"],"explanation":"ask for help 求助。"},{"q":"6","answer":"D","options":["price","song","cloud","hand"],"explanation":"give you a hand 帮你一把。"},{"q":"7","answer":"A","options":["manage","sell","lose","forget"],"explanation":"manage your time 管理时间。"},{"q":"8","answer":"B","options":["prices","others","clouds","songs"],"explanation":"help others 帮助他人。"},{"q":"9","answer":"C","options":["empty","late","welcome","asleep"],"explanation":"feel welcome 感到受欢迎。"},{"q":"10","answer":"D","options":["least","price","cloud","most"],"explanation":"make the most of 充分利用。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Talking About the First Day', '外研社版必修第一册 U1 · dialogue', 3, 'Tom: Hi, Anna! How was your first day at senior high?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·短文 Orientation Day', '外研社版必修第一册 U1 · passage', 2, 'Many schools hold an Orientation Day for new students.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Making a Weekend Study Plan', '外研社版必修第一册 U1 · dialogue', 3, 'Lily: Ben, shall we make a study plan for the weekend?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·短文 A Tip for Taking Notes', '外研社版必修第一册 U1 · passage', 2, 'In senior high, teachers often speak quickly during lessons.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Asking a Senior for Advice', '外研社版必修第一册 U1 · dialogue', 3, 'Kate: Excuse me, you are a senior student, right? Can I ask for some advice?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·短文 A Good Beginning', '外研社版必修第一册 U1 · passage', 2, 'People often say that a good beginning is half the success.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Journal Entry about Your First Week(写一篇高中第一周的日记)', 'My First Week at Senior High', '假设你叫李华,刚升入高中一周。请用英语写一篇约80词的日记,内容包括:① 这一周给你印象最深的一件事(如一节课、一次社团活动、或结识新朋友);② 当时发生了什么、你怎么做的;③ 你的感受以及对未来的期待。注意:用第一人称、过去时为主,句子围绕中心、用恰当的基本句型。', 'Suppose you are Li Hua and you have just finished your first week at senior high. Write a journal entry (about 80 words) including: 1) the most memorable thing this week (e.g. a lesson, a club activity, or making a new friend); 2) what happened and what you did; 3) how you felt and what you look forward to.', '["记叙最难忘的一件事(The thing I remember most this week is …)","说明经过与你的做法(At first … , so I … . Then …)","表达感受与期待(I felt … , and I am really looking forward to …)","第一人称、过去时为主、句子围绕中心、基本句型正确"]'::jsonb, 70, 100, 'Friday, 8 September
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U1', '{"title":"基本句型 Basic Sentence Structures 速查(SVOO / SVOC / SVP)","intro":"英语句子万变不离五种基本句型。先找出谓语动词,再看它后面带什么:带两个宾语(人+物)是 SVOO;带''宾语+补足语''是 SVOC;系动词后接形容词作表语是 SVP。判断的关键是动词的类型和它后面成分的性质。","table":{"headers":["句型","结构 / 例句 / 要点"],"rows":[["SV 主谓","主语 + 不及物动词:The campus + was quiet 之前 I + arrived(后面不带宾语)"],["SVO 主谓宾","主语 + 及物动词 + 宾语:I + saw + a white-haired man"],["SVOO 主谓宾宾","give/tell/show/offer + 人 + 物:He + gave + me + a smile"],["SVOC 主谓宾补","make/keep/find + 宾语 + 形容词:His words + made + me + relaxed"],["SVP 主系表","be/feel/look/become + 形容词:I + felt + nervous"]]},"specialRules":[{"rule":"SVOO 的物主前若加 to/for,就变成''介词短语'',不再是双宾语","mark":"give me a book = give a book to me"},{"rule":"SVOC 与 SVP 的补语/表语都用形容词,不用副词","mark":"made me happy √ / made me happily ×"},{"rule":"系动词后用形容词作表语;实义动词后才用副词作状语","mark":"I felt nervous(系)/ I waited nervously(实义)"},{"rule":"make/let/have sb do:宾补是不带 to 的动词原形","mark":"His words made me feel relaxed √ / made me to feel ×"}],"why":["句型本质是看''谓语动词要求几个、什么样的成分'':不及物动词到 SV 就完整;及物动词要一个宾语(SVO);双宾动词要两个宾语(SVOO);使役/感官类动词要''宾语+补足语''(SVOC);系动词要一个表语(SVP)。抓住动词,就抓住了句型。"],"gaokaoPoints":["SVOC 中宾补的形式高频:形容词(made it clear)、动词原形(let him go)、现在/过去分词(keep it running / get it done)。","系动词后用形容词作表语(语法填空、改错高频):feel/look/sound/taste/smell + adj。","双宾语与''动词+介词短语''的转换:bring me the book = bring the book to me。"],"examVsReal":[{"exam":"His words made me feel relaxed.(考试要求结构完整)","real":"His words really helped me relax.","note":"考试看句型是否成立;真实表达常换更自然的说法,意思相同"},{"exam":"I felt nervous before the speech.(系表 + 形容词)","real":"I had butterflies in my stomach.","note":"考试用''系动词+形容词'';口语爱用生动的习语表达同样的紧张感"}]}'::jsonb, 'fltrp');
